-- Agata Gruvbox lualine theme: Dark or Light according to 'background', which Neovim sets from the
-- terminal background at start-up. Generated by tools/gen-app-themes.py from extras/palette.json.

local variant = vim.o.background == "light" and "light" or "dark"
return dofile(vim.api.nvim_get_runtime_file("lua/lualine/themes/agata-gruvbox-" .. variant .. ".lua", false)[1])
